(function(){
  if(window.__hooked) return "already";
  window.__net=[];
  const of=window.fetch;
  window.fetch=function(u,o){
    try{
      let url=(typeof u==='string')?u:(u&&u.url);
      let entry={url:url,method:(o&&o.method)||'GET'};
      if(o&&o.body&&typeof o.body==='string'){
        try{const j=JSON.parse(o.body);
          if(j.operationName)entry.op=j.operationName;
          if(j.query){const m=j.query.match(/(query|mutation)\s+(\w+)/);if(m)entry.gql=m[2];
            // capture root field
            const rf=j.query.match(/\{\s*(\w+)/);if(rf)entry.root=rf[1];}
          if(j.variables)entry.vars=Object.keys(j.variables);
        }catch(e){entry.body=o.body.slice(0,200);}
      }
      window.__net.push(entry);
    }catch(e){}
    return of.apply(this,arguments);
  };
  return "hooked";
})()
