import json
data=json.load(open('graphql_introspection.json'))
schema=data['data']['__schema']
types={t['name']:t for t in schema['types']}
SCALARS={'String','Int','BigInt','Float','Boolean','ID','Datetime','Date','UUID','JSON','BigFloat','Cursor','Time'}
def base(t):
    cur=t
    while cur:
        if cur.get('name') and cur['kind'] not in ('NON_NULL','LIST'): return cur['name']
        cur=cur.get('ofType')
    return '?'
def tn(t):
    cur=t;pre='';post=''
    while cur:
        k=cur.get('kind')
        if k=='NON_NULL':post='!'+post
        elif k=='LIST':pre+='[';post=']'+post
        else:return pre+(cur.get('name') or '?')+post
        cur=cur.get('ofType')
    return '?'
# entity tables = those with create<Name> mutation
mut=types['Mutation']['fields']
ents=[]
for f in mut:
    if f['name'].startswith('create') and f['name'] not in ('createSequelizeMeta',):
        ents.append(f['name'][6:])
# normalize plural-ish dups
seen=set();entities={}
for e in ents:
    t=types.get(e)
    if not t or not t.get('fields'): continue
    cols=[];rels=[]
    for f in t['fields']:
        b=base(f['type'])
        if f['args']: continue
        if b in SCALARS or types.get(b,{}).get('kind')=='ENUM':
            cols.append({'name':f['name'],'type':tn(f['type'])})
    entities[e]={'columns':cols}
out={'entityCount':len(entities),'entities':entities}
json.dump(out,open('data_model_full.json','w'),indent=1)
print("entities:",len(entities))
print(", ".join(sorted(entities.keys())))
# relationship inference: scan fk columns
print("\n-- FK-like columns per entity --")
for e in sorted(entities):
    fks=[c['name'] for c in entities[e]['columns'] if c['name'].endswith('Id') and c['name'] not in ('nodeId',)]
    if fks: print(f"{e}: {fks}")
