{"file_path":"/Users/mukesh/Claude/communitree-rebuild/app/server/src/db.ts","content":"/**
 * Single shared pg Pool built from DATABASE_URL.
 *
 * pg type coercion notes:
 *   - BIGINT (oid 20) is parsed to JS string by default in node-postgres to
 *     avoid Number precision loss. We keep that default (mobile_no etc. are
 *     strings in our types). Good.
 *   - NUMERIC (oid 1700) is also returned as string by default — matches the
 *     observed REST shape where forest_oxygen is "2069100.00".
 */
import { Pool, types } from 'pg';
import { config } from './config';

// Ensure NUMERIC stays a string (it already is by default; explicit for clarity
// and so forest_oxygen / forest_carbonoffset serialise like the live API).
types.setTypeParser(1700, (val) => val);

export const pool = new Pool({
  connectionString: config.databaseUrl,
});

pool.on('error', (err) => {
  // A backend client in the pool errored unexpectedly (e.g. DB restart).
  // Log and let the next query re-establish a connection.
  // eslint-disable-next-line no-console
  console.error('[db] unexpected pool error', err);
});

/** Thin query helper preserving full pg typing for rows. */
export function query<T extends Record<string, unknown> = Record<string, unknown>>(
  text: string,
  params?: ReadonlyArray<unknown>
) {
  return pool.query<T>(text, params as unknown[] | undefined);
}
"}

