{"file_path":"/Users/mukesh/Claude/communitree-rebuild/app/server/scripts/migrate.js","content":"/**
 * Tiny raw-SQL migration runner. Applies every *.sql file in
 * ../../db/migrations in lexical order against DATABASE_URL.
 *
 * Usage:  npm run migrate
 * (Files are idempotent — CREATE TABLE IF NOT EXISTS / ON CONFLICT DO NOTHING —
 *  so re-running is safe for local dev.)
 */
const fs = require('fs');
const path = require('path');
require('dotenv').config();
const { Pool } = require('pg');

const MIGRATIONS_DIR = path.resolve(__dirname, '..', '..', 'db', 'migrations');

async function main() {
  const pool = new Pool({
    connectionString:
      process.env.DATABASE_URL ||
      'postgres://***',
  });

  const files = fs
    .readdirSync(MIGRATIONS_DIR)
    .filter((f) => f.endsWith('.sql'))
    .sort();

  for (const file of files) {
    const sql = fs.readFileSync(path.join(MIGRATIONS_DIR, file), 'utf8');
    process.stdout.write(`-> applying ${file} ... `);
    await pool.query(sql);
    process.stdout.write('done\n');
  }

  await pool.end();
  console.log('All migrations applied.');
}

main().catch((err) => {
  console.error('Migration failed:', err.message);
  process.exit(1);
});
"}

